parameters.functionCode:
const body = $input.first().json;
const { prompt, duration, mood, genre, bpm, preset } = body;

// 应用风格预设
const presetMap = {
  corporate: { mood: 'professional', genre: 'electronic', bpm: 100, instruments: ['piano','synth','soft_drums'] },
  cinematic: { mood: 'epic', genre: 'orchestral', bpm: 85, instruments: ['strings','brass','piano'] },
  lofi: { mood: 'relaxed', genre: 'lofi', bpm: 80, instruments: ['piano','vinyl','drums'] },
  electronic: { mood: 'energetic', genre: 'electronic', bpm: 128, instruments: ['synth','bass','drums'] },
  ambient: { mood: 'calm', genre: 'ambient', bpm: 60, instruments: ['pad','drone'] }
};

const config = presetMap[preset] || { mood, genre, bpm, instruments: [] };

return [{json: {
  prompt: prompt || `${config.mood} ${config.genre}, ${config.instruments?.join(',')}, ${config.bpm} BPM`,
  duration: duration || 30,
  mood: config.mood,
  genre: config.genre,
  bpm: config.bpm,
  requestId: `music_${Date.now()}`
}}];

const result = $input.first().json;
// 模拟混音参数
return [{json: {
  input_file: result.audio_path || '/tmp/raw_music.wav',
  fade_in: 2,
  fade_out: 2,
  normalize: true,
  bitrate: '320k',
  output_file: '/tmp/mixed_' + (result.requestId || 'music') + '.mp3'
}}];

const body = $input.first().json;
return [
  { json: { ...body, format: 'mp3_320', bitrate: '320k', filename: body.output_file } },
  { json: { ...body, format: 'mp3_128', bitrate: '128k', filename: body.output_file.replace('320k','128k') } },
  { json: { ...body, format: 'wav', bitrate: '1411k', filename: body.output_file.replace('.mp3','.wav') } }
];

